/**
 * Floor-plan evaluation — the vision step that turns a listing's floor plan into metric rooms.
 *
 * This is the accuracy step of the product: a plan that prints `12'-4" × 15'-2"` gives a room an
 * anchor of ±5 cm, better than any tap on a photo. So the task is read exactly as it ships: the same
 * messages, the same JSON schema, and the same normalisation (`planFromJson`), through the same
 * /api/ai/chat proxy, so latency and cost are what a seller pays.
 *
 * Corpus (evals/plans/manifest.json):
 *   - 8 synthetic listing-style plans generated by evals/plans/make-plans.mjs from a room table, so
 *     their ground truth is exact by construction. Feet-and-inches, metres, one mixed-unit sheet, one
 *     two-storey sheet, one with no north arrow.
 *   - the app's own demo plan (a rendered three-storey townhouse, no printed dimensions).
 *   - two public-domain 1911 Guimard apartment plans from Wikimedia Commons: hand-lettered, French,
 *     metric dimensions written by hand. Labelled by what a human can read.
 *
 * Scored: room recall (distinct labels), room-type accuracy, dimension recall, dimension accuracy
 * within 5%, latency and cost. Two systems are scored from the *same* responses, which is the point
 * of the design: **product** re-reads the printed dimension string in code, **model metres** trusts
 * the model's own conversion. The gap between them is what the four lines of arithmetic in
 * `metresFromDimensions` are worth.
 *
 * Run:  npm run dev   then   npm run eval
 * Env:  EVAL_FLOORPLAN_MODELS=vision,zai-org/GLM-5.3-Flash to compare models.
 */
import { describe, expect, it } from 'vitest';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { extractJson, FLOORPLAN_SCHEMA, floorPlanMessages, metresFromDimensions, planFromJson, planRooms, type PlanUnits } from '@/services/floorplan';
import type { RoomType } from '@/engine/types';

const BASE = process.env.EVAL_BASE || 'http://localhost:5173';
const MODELS = (process.env.EVAL_FLOORPLAN_MODELS || 'vision').split(',').map((s) => s.trim()).filter(Boolean);
const DIM_TOLERANCE = 0.05;

interface TruthRoom {
  name: string;
  type: RoomType;
  width?: number;
  depth?: number;
}
interface TruthPlan {
  file: string;
  kind: 'synthetic' | 'real';
  title: string;
  source: string;
  license: string;
  units: PlanUnits | 'none';
  northArrow: boolean | null;
  dimensioned: boolean;
  floors: { label: string; rooms: TruthRoom[] }[];
  note: string;
}

const MIME: Record<string, string> = { '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.webp': 'image/webp' };

/* ---------- matching a predicted room to a labelled one ---------- */

const norm = (s: string) =>
  s
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();

/** `bath` and `bathroom`, `bed 2` and `bedroom 2`: the same room said two ways. */
function tokensAlike(a: string, b: string): boolean {
  if (a === b) return true;
  return a.length >= 3 && b.length >= 3 && (a.startsWith(b) || b.startsWith(a));
}

/** 0..1 name similarity, with any digits in the label required to agree ("Bed 2" is not "Bed 3"). */
function nameScore(a: string, b: string): number {
  const ta = norm(a).split(' ').filter(Boolean);
  const tb = norm(b).split(' ').filter(Boolean);
  if (!ta.length || !tb.length) return 0;
  const da = ta.filter((t) => /^\d+$/.test(t));
  const db = tb.filter((t) => /^\d+$/.test(t));
  if (da.length && db.length && da.join() !== db.join()) return 0;
  let hits = 0;
  const used = new Set<number>();
  for (const x of ta) {
    const j = tb.findIndex((y, k) => !used.has(k) && tokensAlike(x, y));
    if (j >= 0) {
      used.add(j);
      hits += 1;
    }
  }
  return hits / Math.max(ta.length, tb.length);
}

const NAME_THRESHOLD = 0.5;

/** Within 5%, either way round: a plan may print width × depth or depth × width. */
function dimsClose(truth: { width: number; depth: number }, got: { width?: number; depth?: number }): boolean {
  if (got.width == null || got.depth == null) return false;
  const t = [truth.width, truth.depth].sort((a, b) => a - b);
  const g = [got.width, got.depth].sort((a, b) => a - b);
  return t.every((v, i) => Math.abs(g[i] - v) / v <= DIM_TOLERANCE);
}

interface Predicted {
  name: string;
  type: RoomType;
  floor: string;
  width?: number;
  depth?: number;
  dimensionsText?: string;
}

/**
 * Greedy one-to-one matching, best name score first; ties among same-named rooms (three "chambre"s
 * on one Paris plan) are broken by whichever prediction's dimensions are closest, so the score
 * measures whether the numbers were read, not which duplicate the matcher happened to pick.
 */
function matchRooms(truth: TruthRoom[], got: Predicted[]) {
  const pairs: { t: number; g: number; score: number; dim: number }[] = [];
  truth.forEach((tr, ti) =>
    got.forEach((gr, gi) => {
      const score = nameScore(tr.name, gr.name);
      if (score < NAME_THRESHOLD) return;
      const dim =
        tr.width != null && tr.depth != null && gr.width != null && gr.depth != null
          ? Math.abs(gr.width - tr.width) + Math.abs(gr.depth - tr.depth)
          : 99;
      pairs.push({ t: ti, g: gi, score, dim });
    }),
  );
  pairs.sort((a, b) => b.score - a.score || a.dim - b.dim);
  const tTaken = new Set<number>();
  const gTaken = new Set<number>();
  const matched: { truth: TruthRoom; got: Predicted }[] = [];
  for (const p of pairs) {
    if (tTaken.has(p.t) || gTaken.has(p.g)) continue;
    tTaken.add(p.t);
    gTaken.add(p.g);
    matched.push({ truth: truth[p.t], got: got[p.g] });
  }
  return { matched, missed: truth.filter((_, i) => !tTaken.has(i)), extra: got.filter((_, i) => !gTaken.has(i)) };
}

/* ---------- one plan, one system ---------- */

interface Result {
  system: string;
  file: string;
  rooms: number;
  found: number;
  typeOk: number;
  dimTruth: number;
  dimGiven: number;
  dimOk: number;
  extra: number;
  floors: number;
  floorsTruth: number;
  unitsOk: boolean | null;
  northOk: boolean | null;
  ms: number;
  usd: number;
  model?: string;
  error?: string;
  misses: string[];
  dimMisses: string[];
}

function empty(system: string, p: TruthPlan, truth: TruthRoom[], ms: number, usd: number, error?: string): Result {
  return {
    system,
    file: p.file,
    rooms: truth.length,
    found: 0,
    typeOk: 0,
    dimTruth: truth.filter((r) => r.width != null).length,
    dimGiven: 0,
    dimOk: 0,
    extra: 0,
    floors: 0,
    floorsTruth: p.floors.length,
    unitsOk: null,
    northOk: null,
    ms,
    usd,
    misses: truth.map((r) => r.name),
    dimMisses: [],
    error,
  };
}

function score(system: string, p: TruthPlan, truth: TruthRoom[], got: Predicted[], floors: number, units: PlanUnits, north: boolean, ms: number, usd: number, model?: string): Result {
  const { matched, missed, extra } = matchRooms(truth, got);
  const dimMisses: string[] = [];
  let typeOk = 0;
  let dimGiven = 0;
  let dimOk = 0;
  let dimTruth = 0;
  for (const m of matched) {
    if (m.truth.type === m.got.type) typeOk += 1;
    if (m.truth.width == null || m.truth.depth == null) continue;
    dimTruth += 1;
    if (m.got.width != null && m.got.depth != null) {
      dimGiven += 1;
      if (dimsClose({ width: m.truth.width, depth: m.truth.depth }, m.got)) dimOk += 1;
      else dimMisses.push(`${m.truth.name}: ${m.truth.width}×${m.truth.depth} m read as ${m.got.width}×${m.got.depth} m${m.got.dimensionsText ? ` (printed "${m.got.dimensionsText}")` : ''}`);
    } else {
      dimMisses.push(`${m.truth.name}: ${m.truth.width}×${m.truth.depth} m, no dimensions returned`);
    }
  }
  // Rooms the model missed entirely still had dimensions to read.
  dimTruth += missed.filter((r) => r.width != null).length;
  return {
    system,
    file: p.file,
    rooms: truth.length,
    found: matched.length,
    typeOk,
    dimTruth,
    dimGiven,
    dimOk,
    extra: extra.length,
    floors,
    floorsTruth: p.floors.length,
    unitsOk: p.units === 'none' ? null : units === p.units,
    northOk: p.northArrow == null ? null : north === p.northArrow,
    ms,
    usd,
    model,
    misses: missed.map((r) => r.name),
    dimMisses,
  };
}

/** The model's own metres, without our re-reading of the printed string. */
function modelOnlyRooms(j: any): Predicted[] {
  const out: Predicted[] = [];
  for (const f of Array.isArray(j?.floors) ? j.floors : []) {
    for (const r of Array.isArray(f?.rooms) ? f.rooms : []) {
      const name = String(r?.name ?? '').trim();
      if (!name) continue;
      const w = Number(r?.width_m);
      const d = Number(r?.depth_m);
      const ok = Number.isFinite(w) && Number.isFinite(d) && w > 0.3 && d > 0.3 && w < 60 && d < 60;
      out.push({ name, type: r?.type, floor: String(f?.label ?? ''), width: ok ? w : undefined, depth: ok ? d : undefined, dimensionsText: r?.dimensions_text });
    }
  }
  return out;
}

/** Our converter run over the model's verbatim strings, without the model's arithmetic. */
function textOnlyRooms(j: any, units: PlanUnits): Predicted[] {
  return modelOnlyRooms(j).map((r) => {
    const read = r.dimensionsText ? metresFromDimensions(r.dimensionsText, units) : undefined;
    return { ...r, width: read?.width, depth: read?.depth };
  });
}

/** The product's own reader, salvage and all — the eval must not be more forgiving than the app. */
const extract = extractJson;

/* ---------- summaries ---------- */

function summarize(results: Result[]) {
  const by = new Map<string, Result[]>();
  for (const r of results) by.set(r.system, [...(by.get(r.system) || []), r]);
  return [...by].map(([system, list]) => {
    const sum = (f: (r: Result) => number) => list.reduce((a, r) => a + f(r), 0);
    const rooms = sum((r) => r.rooms);
    const found = sum((r) => r.found);
    const dimTruth = sum((r) => r.dimTruth);
    const pct = (a: number, b: number) => (b ? Math.round((a / b) * 100) : null);
    const unitsScored = list.filter((r) => r.unitsOk != null);
    const northScored = list.filter((r) => r.northOk != null);
    return {
      system,
      plans: list.length,
      rooms,
      recallPct: pct(found, rooms),
      typePct: pct(sum((r) => r.typeOk), found),
      dimRecallPct: pct(sum((r) => r.dimGiven), dimTruth),
      dimAccPct: pct(sum((r) => r.dimOk), dimTruth),
      extraRooms: sum((r) => r.extra),
      floorsPct: pct(list.filter((r) => r.floors === r.floorsTruth).length, list.length),
      unitsPct: unitsScored.length ? pct(unitsScored.filter((r) => r.unitsOk).length, unitsScored.length) : null,
      northPct: northScored.length ? pct(northScored.filter((r) => r.northOk).length, northScored.length) : null,
      errors: list.filter((r) => r.error).length,
      meanMs: Math.round(sum((r) => r.ms) / list.length),
      meanUsd: Number((sum((r) => r.usd) / list.length).toFixed(5)),
      totalUsd: Number(sum((r) => r.usd).toFixed(4)),
    };
  });
}

const pctCell = (v: number | null) => (v == null ? '—' : `${v}%`);

describe('floor-plan evaluation', () => {
  it('scores the plan parser against hand-labelled and synthetic listing plans', async () => {
    const startedAt = new Date().toISOString();
    const dir = path.resolve(process.cwd(), 'evals/plans');
    const manifest = JSON.parse(readFileSync(path.join(dir, 'manifest.json'), 'utf8')) as { plans: TruthPlan[]; note: string };
    const truthOf = (p: TruthPlan) => p.floors.flatMap((f) => f.rooms);

    const results: Result[] = [];
    // Baseline: what the product does with no model at all — an empty plan and one honest note.
    for (const p of manifest.plans) results.push(empty('no-model baseline', p, truthOf(p), 0, 0));

    let live = false;
    try {
      const st: any = await (await fetch(`${BASE}/api/status`)).json();
      live = Boolean(st.nebius);
    } catch {
      live = false;
    }

    if (live) {
      for (const model of MODELS) {
        for (const p of manifest.plans) {
          const truth = truthOf(p);
          const ext = path.extname(p.file).toLowerCase();
          const dataUrl = `data:${MIME[ext] || 'image/png'};base64,${readFileSync(path.join(dir, p.file)).toString('base64')}`;
          const t0 = Date.now();
          let body: any = {};
          let ok = false;
          try {
            const r = await fetch(`${BASE}/api/ai/chat`, {
              method: 'POST',
              headers: { 'content-type': 'application/json' },
              body: JSON.stringify({ task: `eval_floorplan_${model}`, model, messages: floorPlanMessages(dataUrl), schema: FLOORPLAN_SCHEMA, schemaName: 'floorplan', temperature: 0.1, max_tokens: 4000 }),
            });
            body = await r.json();
            ok = r.ok;
          } catch (e: any) {
            body = { error: e?.message };
          }
          const ms = body.ms ?? Date.now() - t0;
          const usd = body.usd ?? 0;
          if (!ok) {
            results.push(empty(`${model} · product`, p, truth, ms, usd, body.error || 'request failed'));
            continue;
          }
          let j: any;
          try {
            j = extract(body.content);
          } catch (e: any) {
            results.push(empty(`${model} · product`, p, truth, ms, usd, `parse: ${e?.message}`));
            continue;
          }
          const plan = planFromJson(j);
          const north = Boolean(plan.northArrow);
          results.push(score(`${model} · product`, p, truth, planRooms(plan), plan.floors.length, plan.units, north, ms, usd, body.model));
          // Same response, two ablations: the model's own arithmetic, and ours on its verbatim text.
          results.push(score(`${model} · model metres`, p, truth, modelOnlyRooms(j), plan.floors.length, plan.units, north, ms, usd, body.model));
          results.push(score(`${model} · printed text only`, p, truth, textOnlyRooms(j, plan.units), plan.floors.length, plan.units, north, ms, usd, body.model));
        }
      }
    } else {
      console.warn('Dev server not reachable or NEBIUS_API_KEY missing: only the no-model baseline was scored.');
    }

    // The ablations share every response with the product run, so they cost nothing extra.
    for (const r of results) if (/model metres|printed text only/.test(r.system)) r.usd = 0;

    const rows = summarize(results);
    console.table(rows);

    const outDir = path.resolve(process.cwd(), 'evals/results');
    mkdirSync(outDir, { recursive: true });
    const stamp = startedAt.replace(/[:.]/g, '-');
    writeFileSync(path.join(outDir, `floorplan-${stamp}.json`), JSON.stringify({ startedAt, base: BASE, models: MODELS, rows, results }, null, 2));

    const lines: string[] = [];
    const totalRooms = manifest.plans.reduce((a, p) => a + truthOf(p).length, 0);
    const totalDims = manifest.plans.reduce((a, p) => a + truthOf(p).filter((r) => r.width != null).length, 0);
    lines.push(`# Floor-plan evaluation — ${startedAt}`);
    lines.push('');
    lines.push(
      `${manifest.plans.length} plans, ${totalRooms} labelled rooms, ${totalDims} of them with printed dimensions (evals/plans/manifest.json). Eight are synthetic listing-style sheets generated from a room table, so their ground truth is exact; the other three are real — the app's own demo townhouse plan and two public-domain 1911 Guimard apartment plans from Wikimedia Commons, labelled by what a human can read.`,
    );
    lines.push('');
    lines.push(
      `**Systems.** All three read the *same* responses, so the differences are normalisation, not modelling — and they cost nothing extra. *product* is what ships: the vision model returns each printed dimension string verbatim, \`metresFromDimensions\` converts it here, and \`planFromJson\` also drops nameless rooms, empty floors and a stuck decoder's repeated rooms. *model metres* takes the model's own \`width_m\`/\`depth_m\` straight from the JSON with none of that. *printed text only* is our converter with no model arithmetic to fall back on. Dimensions count as correct within ${DIM_TOLERANCE * 100}% on both sides; a room counts as found when its label matches (distinct labels only, so a plan that repeats "Chambre" scores it once), and "extra rooms" counts predictions that matched no label.`,
    );
    lines.push('');
    lines.push('| system | plans | rooms | room recall | type | dims returned | dims within 5% | extra rooms | floors | units | north arrow | errors | mean ms | mean $ | total $ |');
    lines.push('| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |');
    for (const r of rows) {
      lines.push(
        `| ${r.system} | ${r.plans} | ${r.rooms} | ${pctCell(r.recallPct)} | ${pctCell(r.typePct)} | ${pctCell(r.dimRecallPct)} | ${pctCell(r.dimAccPct)} | ${r.extraRooms} | ${pctCell(r.floorsPct)} | ${pctCell(r.unitsPct)} | ${pctCell(r.northPct)} | ${r.errors} | ${r.meanMs} | ${r.meanUsd} | ${r.totalUsd} |`,
      );
    }
    lines.push('');
    lines.push('## Per plan (product)');
    lines.push('');
    lines.push('| plan | kind | rooms found | type ok | dims within 5% | extra | floors | ms | $ | note |');
    lines.push('| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |');
    for (const r of results.filter((x) => x.system.endsWith('· product'))) {
      const p = manifest.plans.find((x) => x.file === r.file)!;
      lines.push(
        `| ${r.file} | ${p.kind} | ${r.found}/${r.rooms} | ${r.typeOk}/${r.found} | ${r.dimOk}/${r.dimTruth} | ${r.extra} | ${r.floors}/${r.floorsTruth} | ${r.ms} | ${r.usd.toFixed(5)} | ${r.error ?? p.note} |`,
      );
    }
    const struggles = results.filter((x) => x.system.endsWith('· product') && (x.misses.length || x.dimMisses.length));
    if (struggles.length) {
      lines.push('');
      lines.push('## Struggle cases');
      lines.push('');
      for (const s of struggles) {
        lines.push(`- **${s.file}**`);
        if (s.misses.length) lines.push(`  - rooms not found: ${s.misses.join(', ')}`);
        for (const d of s.dimMisses) lines.push(`  - ${d}`);
      }
    }
    const product = rows.find((r) => r.system.endsWith('· product'));
    const modelOnly = rows.find((r) => r.system.endsWith('· model metres'));
    if (product && modelOnly) {
      lines.push('');
      lines.push('## What this says');
      lines.push('');
      lines.push(
        `Reading the printed string in code rather than trusting the model's conversion is worth ${product.dimAccPct! - modelOnly.dimAccPct!} points of dimension accuracy (${modelOnly.dimAccPct}% → ${product.dimAccPct}%), and the normalisation pass removes ${modelOnly.extraRooms - product.extraRooms} phantom rooms the raw JSON would have turned into rooms in the seller's tour. Both are free.`,
      );
      lines.push('');
      lines.push(
        `Cost and latency are what a seller pays: ${product.meanMs} ms and $${product.meanUsd} for a whole listing's plan, against ±30 cm of guesswork with no plan at all.`,
      );
    }
    lines.push('');
    lines.push(`Corpus provenance: ${manifest.note}`);
    writeFileSync(path.join(outDir, 'floorplan-latest.md'), lines.join('\n') + '\n');

    expect(rows.length).toBeGreaterThan(0);
  });
});
